def transform(grid):
 out=[row[:] for row in grid]
 for r,row in enumerate(grid):
  for c,v in enumerate(row):
   if v==5:
    # fill from nearest outer vertical border toward the marker
    left=next((j for j in range(c-1,-1,-1) if grid[r][j]==2),None)
    right=next((j for j in range(c+1,len(row)) if grid[r][j]==2),None)
    if left is not None:
     for j in range(left+1,c):out[r][j]=5
    elif right is not None:
     for j in range(c+1,right):out[r][j]=5
    out[r][c]=4
 return out
